package io.fireflysoftware.common.config.core.authority;
import io.fireflysoftware.common.config.models.entities.tenantbinding.TenantResourceBindingRows.*;
import io.fireflysoftware.common.config.models.repositories.tenantbinding.impl.TenantResourceBindingStoreImpl;
import org.junit.jupiter.api.Test;
import org.springframework.data.r2dbc.core.*;
import org.springframework.data.r2dbc.dialect.PostgresDialect;
import org.springframework.data.relational.core.query.*;
import org.springframework.r2dbc.core.*;
import reactor.core.publisher.Mono;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class TenantResourceBindingStoreTest {
 @Test void currentReadUsesOnlyTheProtectedSnapshotAndExactNamespace(){var template=mock(R2dbcEntityTemplate.class);var select=mock(ReactiveSelectOperation.ReactiveSelect.class,RETURNS_SELF);doReturn(select).when(template).select(Snapshot.class);when(select.one()).thenReturn(Mono.empty());var store=new TenantResourceBindingStoreImpl(template);var digest="a".repeat(64);assertNull(store.current(digest).block());var query=org.mockito.ArgumentCaptor.forClass(Query.class);verify(select).matching(query.capture());assertTrue(query.getValue().getCriteria().orElseThrow().toString().contains("namespaceDigest"));assertTrue(query.getValue().getCriteria().orElseThrow().toString().contains(digest));verify(template,never()).select(Definition.class);}
 @Test void assignedImmutableInsertUsesMappedStatementAndExactAffectedCount(){var database=mock(DatabaseClient.class);var spec=mock(DatabaseClient.GenericExecuteSpec.class);var fetch=mock(FetchSpec.class);doReturn(spec).when(database).sql(any(org.springframework.r2dbc.core.PreparedOperation.class));when(spec.fetch()).thenReturn(fetch);when(fetch.rowsUpdated()).thenReturn(Mono.just(1L));var store=new TenantResourceBindingStoreImpl(new R2dbcEntityTemplate(database,PostgresDialect.INSTANCE));var d=TenantResourceBindingServiceTest.definition();var row=new Definition(d.bindingId(),1,TenantResourceBindingCodec.namespaceDigest(d.namespace()),d.namespace().issuer(),d.namespace().platformTenant(),d.resourceTenant().value(),TenantResourceBindingCodec.definitionDigest(d),4,TenantResourceBindingServiceTest.S,7,d.notAfterEpochMillis(),d.namespace().issuer(),"original-maker");assertNull(store.insertDefinition(row).block());var query=org.mockito.ArgumentCaptor.forClass(org.springframework.r2dbc.core.PreparedOperation.class);verify(database).sql(query.capture());assertTrue(query.getValue().toQuery().contains("cfg_tenant_resource_binding_definition"));assertTrue(query.getValue().toQuery().contains("INSERT INTO"));when(fetch.rowsUpdated()).thenReturn(Mono.just(0L));assertThrows(Exception.class,()->store.insertDefinition(row).block());when(fetch.rowsUpdated()).thenReturn(Mono.just(2L));assertThrows(Exception.class,()->store.insertDefinition(row).block());}
 @Test void compareAndSetBindsTheEntireExpectedHeadAndRefusesZeroRows(){var template=mock(R2dbcEntityTemplate.class);var update=mock(ReactiveUpdateOperation.ReactiveUpdate.class,RETURNS_SELF);doReturn(update).when(template).update(Head.class);when(update.apply(any(Update.class))).thenReturn(Mono.just(0L));var store=new TenantResourceBindingStoreImpl(template);var old=new Head("a".repeat(64),TenantResourceBindingServiceTest.B,1,"b".repeat(64),4,"ACTIVE");var next=new Head(old.namespaceDigest(),old.bindingId(),1,old.definitionDigest(),5,"REVOKED");assertThrows(Exception.class,()->store.advance(old,next).block());var query=org.mockito.ArgumentCaptor.forClass(Query.class);verify(update).matching(query.capture());var where=query.getValue().getCriteria().orElseThrow().toString();for(var field:new String[]{"namespaceDigest","bindingId","definitionVersion","definitionDigest","controlVersion","state"})assertTrue(where.contains(field));when(update.apply(any(Update.class))).thenReturn(Mono.just(1L));assertNull(store.advance(old,next).block());}
 @Test void invalidNamespaceAndControlTransitionsFailBeforeDatabaseAccess(){var template=mock(R2dbcEntityTemplate.class);var store=new TenantResourceBindingStoreImpl(template);assertThrows(Exception.class,()->store.current("not-a-digest").block());var old=new Head("a".repeat(64),TenantResourceBindingServiceTest.B,1,"b".repeat(64),4,"ACTIVE");assertThrows(Exception.class,()->store.advance(old,new Head(old.namespaceDigest(),old.bindingId(),1,old.definitionDigest(),6,"REVOKED")).block());verifyNoInteractions(template);}
}
